### Implementation Summary

- **`CanvasStateManager`** ([state-crdt.ts](file:////workspace/realtime-collab-board/state-crdt.ts#L751-L764)): `undo(peerId)` and `redo(peerId)` locate the most recent snapshot in `undoStack` / `redoStack` containing changes authored by `peerId`, push the current peer elements to the opposite stack, restore the snapshot elements with incremented `version` (so LWW `applyRemotePatch` on peers accepts the rollback/rollforward), and return the updated `WhiteboardElement[]` for broadcasting via [`SyncSocketClient.broadcastElement`](file:////workspace/realtime-collab-board/ws-client.ts#L655-L659).
- **`CanvasRenderer`** ([canvas-engine.ts](file:////workspace/realtime-collab-board/canvas-engine.ts#L821-L836)): `computeDirtyBounds(before, after)` diffs element states by `id` (detecting added, removed, or geometry/style-mutated elements) and computes the union bounding box `{ minX, minY, maxX, maxY }` of both previous and new positions for partial canvas invalidation.

```typescript
// In CanvasStateManager (state-crdt.ts)
public undo(peerId: string): WhiteboardElement[] {
  for (let i = this.undoStack.length - 1; i >= 0; i--) {
    const snapshot = this.undoStack[i];
    if (!snapshot.some((el) => el.authorId === peerId)) continue;

    this.undoStack.splice(i, 1);
    const currentPeerState: WhiteboardElement[] = [];
    const updated: WhiteboardElement[] = [];

    for (const prev of snapshot) {
      if (prev.authorId !== peerId) continue;
      const cur = this.elements.get(prev.id);
      if (cur) currentPeerState.push({ ...cur });

      const nextVersion = (cur ? Math.max(cur.version, prev.version) : prev.version) + 1;
      const restored: WhiteboardElement = { ...prev, version: nextVersion, authorId: peerId };
      this.elements.set(restored.id, restored);
      updated.push(restored);
    }

    if (currentPeerState.length > 0) this.redoStack.push(currentPeerState);
    return updated;
  }
  return [];
}

public redo(peerId: string): WhiteboardElement[] {
  for (let i = this.redoStack.length - 1; i >= 0; i--) {
    const snapshot = this.redoStack[i];
    if (!snapshot.some((el) => el.authorId === peerId)) continue;

    this.redoStack.splice(i, 1);
    const currentPeerState: WhiteboardElement[] = [];
    const updated: WhiteboardElement[] = [];

    for (const next of snapshot) {
      if (next.authorId !== peerId) continue;
      const cur = this.elements.get(next.id);
      if (cur) currentPeerState.push({ ...cur });

      const nextVersion = (cur ? Math.max(cur.version, next.version) : next.version) + 1;
      const restored: WhiteboardElement = { ...next, version: nextVersion, authorId: peerId };
      this.elements.set(restored.id, restored);
      updated.push(restored);
    }

    if (currentPeerState.length > 0) this.undoStack.push(currentPeerState);
    return updated;
  }
  return [];
}

