public computeDirtyBounds(
  before: WhiteboardElement[],
  after: WhiteboardElement[]
): { minX: number; minY: number; maxX: number; maxY: number } {
  const beforeMap = new Map(before.map((el) => [el.id, el]));
  const afterMap = new Map(after.map((el) => [el.id, el]));
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

  const expand = (el: WhiteboardElement) => {
    const x1 = Math.min(el.x, el.x + el.width);
    const y1 = Math.min(el.y, el.y + el.height);
    const x2 = Math.max(el.x, el.x + el.width);
    const y2 = Math.max(el.y, el.y + el.height);
    if (x1 < minX) minX = x1;
    if (y1 < minY) minY = y1;
    if (x2 > maxX) maxX = x2;
    if (y2 > maxY) maxY = y2;
  };

  const isChanged = (a: WhiteboardElement, b: WhiteboardElement) =>
    a.x !== b.x || a.y !== b.y || a.width !== b.width ||
    a.height !== b.height || a.stroke !== b.stroke || a.type !== b.type;

  for (const [id, prev] of beforeMap) {
    const curr = afterMap.get(id);
    if (!curr || isChanged(prev, curr)) {
      expand(prev);
      if (curr) expand(curr);
    }
  }
  for (const [id, curr] of afterMap) {
    if (!beforeMap.has(id)) expand(curr);
  }

  return minX === Infinity
    ? { minX: 0, minY: 0, maxX: 0, maxY: 0 }
    : { minX, minY, maxX, maxY };
}
